'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var format = require( '@stdlib/string/format' );
var validate = require( '@stdlib/utils/json-patch/validate' );
var add = require( '@stdlib/utils/json-patch/ops/add' );
var remove = require( '@stdlib/utils/json-patch/ops/remove' );
var replace = require( '@stdlib/utils/json-patch/ops/replace' );
var move = require( '@stdlib/utils/json-patch/ops/move' );
var copyOp = require( '@stdlib/utils/json-patch/ops/copy' );
var testOp = require( '@stdlib/utils/json-patch/ops/test-op' );


// VARIABLES //

/**
* Hash-table dispatch map.
*/
var handlers = {
	'add': handleAdd,
	'remove': handleRemove,
	'replace': handleReplace,
	'move': handleMove,
	'copy': handleCopy,
	'test': handleTest
};


// FUNCTIONS //

/**
* Handles an `add` operation.
*
* @private
* @param {(Object|Array)} doc - current document
* @param {Object} op - operation object
* @returns {(Object|Array)} new document
*/
function handleAdd( doc, op ) {
	return add( doc, op.path, op.value );
}

/**
* Handles a `remove` operation.
*
* @private
* @param {(Object|Array)} doc - current document
* @param {Object} op - operation object
* @returns {(Object|Array)} new document
*/
function handleRemove( doc, op ) {
	return remove( doc, op.path );
}

/**
* Handles a `replace` operation.
*
* @private
* @param {(Object|Array)} doc - current document
* @param {Object} op - operation object
* @returns {(Object|Array)} new document
*/
function handleReplace( doc, op ) {
	return replace( doc, op.path, op.value );
}

/**
* Handles a `move` operation.
*
* @private
* @param {(Object|Array)} doc - current document
* @param {Object} op - operation object
* @returns {(Object|Array)} new document
*/
function handleMove( doc, op ) {
	return move( doc, op.from, op.path );
}

/**
* Handles a `copy` operation.
*
* @private
* @param {(Object|Array)} doc - current document
* @param {Object} op - operation object
* @returns {(Object|Array)} new document
*/
function handleCopy( doc, op ) {
	return copyOp( doc, op.from, op.path );
}

/**
* Handles a `test` operation.
*
* @private
* @param {(Object|Array)} doc - current document
* @param {Object} op - operation object
* @throws {Error} test operation failed
* @returns {(Object|Array)} document unchanged
*/
function handleTest( doc, op ) {
	if ( !testOp( doc, op.path, op.value ) ) {
		throw new Error( format( 'invalid operation. Test operation failed. Path: `%s`. Expected: `%s`.', op.path, JSON.stringify( op.value ) ) );
	}
	return doc;
}


// MAIN //

/**
* Applies an entire JSON Patch (array of operations) to a document atomically.
*
* ## Notes
*
* -   Implements the patch application per RFC 6902 §5.
* -   Operations are applied sequentially in array order.
* -   If any operation fails, the entire patch has no effect (the original document is untouched due to structural sharing).
* -   The operations array is validated before application.
* -   Returns a new document; the original is not modified.
*
* @param {(Object|Array)} document - source JSON document
* @param {Array} operations - array of JSON Patch operation objects
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a valid operations array
* @throws {Error} operations must be structurally valid
* @throws {Error} individual operations may throw on invalid paths or values
* @returns {(Object|Array)} new document with all operations applied
*
* @example
* var doc = { 'foo': 'bar' };
* var ops = [
*     { 'op': 'replace', 'path': '/foo', 'value': 'baz' },
*     { 'op': 'add', 'path': '/qux', 'value': 42 }
* ];
* var out = apply( doc, ops );
* // returns { 'foo': 'baz', 'qux': 42 }
*
* @example
* var doc = { 'foo': [ 1, 2, 3 ] };
* var ops = [
*     { 'op': 'add', 'path': '/foo/-', 'value': 4 },
*     { 'op': 'remove', 'path': '/foo/0' }
* ];
* var out = apply( doc, ops );
* // returns { 'foo': [ 2, 3, 4 ] }
*/
function apply( document, operations ) {
	var current;
	var err;
	var op;
	var i;

	if ( !isPlainObject( document ) && !isArray( document ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be an object or an array. Value: `%s`.', document ) );
	}

	// Validate the operations array structure before applying:
	err = validate( operations );
	if ( err ) {
		throw err;
	}

	// Apply operations sequentially:
	current = document;
	for ( i = 0; i < operations.length; i++ ) {
		op = operations[ i ];
		current = handlers[ op.op ]( current, op );
	}
	return current;
}


// EXPORTS //

module.exports = apply;
